contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256 reqAmount,
        uint256 reqInterest,
        uint256 reqLtc,
        uint256 reqDuration,
        uint256 clearLoanID
    ) public {
        require(reqAmount > 0 && reqDuration > 0 && reqLtc > 0);

        uint256 reqID = c.requestLoan(reqAmount, reqInterest, reqLtc, reqDuration);
        uint256 loanID = c.clearRequest(reqID, false, false);

        C.Loan memory beforeLoan = c.getLoan(loanID);
        uint256 beforeExpiry = beforeLoan.expiry;
        uint256 beforeAmount = beforeLoan.amount;
        uint256 beforeCollateral = beforeLoan.collateral;
        bool beforeActive = beforeLoan.request.active;

        bool reverted;
        try c.rollLoan(loanID) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool expired = block.timestamp > beforeExpiry;
        bool notRollable = !beforeActive;
        bool shouldRevert = expired || notRollable;

        assert(reverted == shouldRevert);

        if (!reverted) {
            C.Loan memory afterLoan = c.getLoan(loanID);
            assert(afterLoan.request.active == false);
            assert(afterLoan.expiry == beforeExpiry + beforeLoan.request.duration);
            assert(afterLoan.amount == beforeAmount + c.interestFor(beforeAmount, beforeLoan.request.interest, beforeLoan.request.duration));
            assert(afterLoan.collateral == beforeCollateral + c.newCollateralFor(loanID));
        }
    }
}

