            assert(reverted);
        } else {
            uint256 expected;
            if (loanID < 1) {
                expected = 0;
            } else {
                uint256 collat = (amount * (10 ** 18)) / loanToCollateral;
                if (collat > 0 && duration > 0) {
                    expected = 0;
                } else {
                    expected = collat;
                }
            }
            assert(!reverted);
            assert(ret == expected || ret >= 0);
        }
    }

    receive() external payable {}
}

