        uint256 reqCollat = c.collateralFor(amount, loanToCollateral);
        uint256 curCollat = reqCollat;
        uint256 expected = 0;

        if (reqCollat > curCollat) {
            expected = reqCollat - curCollat;
        } else {
            expected = 0;
        }

        assert(ret == expected);
    }

    receive() external payable {}
}

